<script>
 import {excludeKnownTaskResults} from '../services/task-output.ts';
 import {onMount} from 'svelte';import {FolderOpen,Grid2X2,List,Search,ChevronDown,ImagePlus} from 'lucide-svelte';import AssetGrid from './AssetGrid.svelte';import RatioBar from './RatioBar.svelte';import Resizer from '../ui/Resizer.svelte';import Button from '../ui/Button.svelte';import {assets} from '../stores/assets.svelte';import {selection} from '../stores/selection.svelte';import {project} from '../stores/project.svelte';import {studio} from '../studio.svelte';import {shell,saveShell,navigate} from '../app/shell.svelte';import {editorUrl,libraryUrl} from '../lib/router.ts';import {libraryOperation,createLibraryProject,findDirectoryProject} from '../services/library.js';import {importChatFiles} from '../services/chat-files.js';import {chooseProductDirectory,droppedProductFiles} from '../services/new-product-files.ts';import {keyboard,shortcutScope,isEditableTarget} from '../lib/shortcuts.ts';
 let menu=$state(null),batch=$state(false),error=$state(''),picker,importing=$state(false);
 const all=$derived(project.items.find(p=>p.id===project.currentId)?.assets.filter(asset=>!asset.trashed)||[]),folders=$derived([...new Set(all.flatMap(asset=>{const path=asset.folderId||'';return path?path.split('/').map((_,i)=>path.split('/').slice(0,i+1).join('/')):[];}))].sort()),tags=$derived([...new Set(all.flatMap(asset=>asset.tags||[]))].sort());
 const ids=$derived(assets.filteredIds);
 function filter(patch){assets.setFilter(patch);navigate(libraryUrl(assets.filter),{replace:true});}
 function context(event,id){if(!selection.selectedIds.includes(id))selection.set([id]);menu={x:Math.min(event.clientX,window.innerWidth-280),y:Math.min(event.clientY,window.innerHeight-310)};batch=false;}
 async function action(kind){error='';try{await libraryOperation(kind);}catch(e){error=e.message;}menu=null;batch=false;}
 function mention(){selection.mention(selection.selectedIds);shell.chatCollapsed=false;saveShell();menu=null;batch=false;}
 function open(){const id=selection.selectedIds[0];if(id)navigate(editorUrl(id));menu=null;}
 async function importFiles(files,options={}){importing=true;error='';try{await importChatFiles(files,options);}catch(e){error=e.message;}finally{importing=false;}}
 async function dropped(event){event.preventDefault();event.stopPropagation();try{await importFiles(await droppedProductFiles(event.dataTransfer,5000));}catch(e){error=e.message;}}
 async function folder(){error='';importing=true;try{const source=await chooseProductDirectory(5000);let id=await findDirectoryProject(source.directory);if(!id)id=(await createLibraryProject(source.label)).id;project.select(id);shell.projectId=id;assets.setFilter({folder:'',tag:'',status:'',q:'',sort:''});saveShell();navigate('/library',{replace:true});const originalFiles=await excludeKnownTaskResults(source.files,id,source.directory,source.relativeFolders);if(originalFiles.length)await importChatFiles(originalFiles,{relativeFolders:source.relativeFolders});if(!error)await project.attachDirectory(source.directory);}catch(e){if(e.name!=='AbortError')error=e.message;}finally{importing=false;}}
 function keys(event){if(isEditableTarget(event.target)||event.target.closest('button:not(.asset-tile)'))return;if(event.ctrlKey||event.metaKey){if(event.key.toLowerCase()==='a'){event.preventDefault();event.stopPropagation();selection.set(ids);}}else if(event.key==='Delete'){if(!selection.selectedIds.length)return;event.preventDefault();event.stopPropagation();void action('trash');}else if(event.key==='Enter'){event.preventDefault();event.stopPropagation();const id=event.target.closest('.asset-tile')?.dataset.assetId;if(id){selection.set([id]);navigate(editorUrl(id));}else open();}}
</script>
<section ondragover={event=>{event.preventDefault();event.stopPropagation();}} ondrop={dropped} style:--tree-w={`${shell.treeWidth}px`} class="asset-library" aria-label="素材库" use:keyboard={{keydown:keys}} use:shortcutScope={{name:'library-menu',exclusive:!!(menu||batch),bindings:menu||batch?[{key:'Escape',action:()=>{menu=null;batch=false;}}]:[]}}>
 <aside class="asset-tree"><h2>文件夹</h2><button class:chosen={!assets.filter.folder} onclick={()=>filter({folder:''})}>全部素材 <small>{all.length}</small></button>{#each folders as folder}<button class:chosen={assets.filter.folder===folder} style:padding-left={`${12+(folder.split('/').length-1)*12}px`} onclick={()=>filter({folder})}><FolderOpen size={13}/><span>{folder.split('/').at(-1)}</span></button>{/each}
 <h2>标签</h2>{#if !tags.length}<p>尚无标签</p>{/if}{#each tags as tag}<button class:chosen={assets.filter.tag===tag} onclick={()=>filter({tag:assets.filter.tag===tag?'':tag})}>{tag}</button>{/each}
 <h2>智能分组</h2><button class:chosen={assets.filter.status==='unanalyzed'} onclick={()=>filter({status:assets.filter.status==='unanalyzed'?'':'unanalyzed'})}>未分析</button>{#each tags as tag}<button class:chosen={assets.filter.tag===tag} onclick={()=>filter({tag:assets.filter.tag===tag?'':tag})}>{tag}</button>{/each}
 </aside><Resizer label="文件夹树宽度" bind:value={shell.treeWidth} min={180} max={320} initial={220} onchange={saveShell}/>
 <div class="asset-library-main"><header class="asset-filters"><label class="asset-search"><Search size={14}/><input type="search" aria-label="搜索素材" placeholder="搜索文件名…" value={assets.filter.q} oninput={event=>filter({q:event.currentTarget.value})}/></label><select aria-label="标签筛选" value={assets.filter.tag} onchange={event=>filter({tag:event.currentTarget.value})}><option value="">全部标签</option>{#each tags as tag}<option value={tag}>{tag}</option>{/each}</select><select aria-label="状态筛选" value={assets.filter.status} onchange={event=>filter({status:event.currentTarget.value})}><option value="">全部状态</option><option value="running">处理中</option><option value="failed">失败</option><option value="idle">待处理</option><option value="unanalyzed">未分析</option></select><select aria-label="素材排序" value={assets.filter.sort} onchange={event=>filter({sort:event.currentTarget.value})}><option value="">原有顺序</option><option value="name">文件名升序</option><option value="name-desc">文件名降序</option></select><button aria-label="网格视图" title="网格视图" class:chosen={shell.view==='grid'} onclick={()=>{shell.view='grid';saveShell();}}><Grid2X2 size={16}/></button><button aria-label="列表视图" title="列表视图" class:chosen={shell.view==='list'} onclick={()=>{shell.view='list';saveShell();}}><List size={16}/></button></header>
 {#if error}<div class="asset-error" role="alert">{error}<Button onclick={()=>error=''}>关闭</Button></div>{/if}
 {#if importing}<div class="asset-empty" role="status">正在导入图片…</div>{:else if !all.length}<div class="asset-empty"><h2>添加第一组图片</h2><p>拖入原图，或选择文件夹。</p><Button onclick={()=>picker.click()}><ImagePlus size={15}/>添加图片</Button><Button onclick={folder}><FolderOpen size={15}/>打开文件夹</Button></div>{:else if !ids.length}<div class="asset-empty"><h2>没有匹配的素材</h2><Button onclick={()=>{filter({folder:'',tag:'',status:'',q:''});}}>清空筛选</Button></div>{:else}<AssetGrid {ids} onmenu={context}/>{/if}
 <input class="ui-sr-only" tabindex="-1" type="file" bind:this={picker} multiple accept="image/png,image/jpeg,image/webp" aria-label="添加素材图片" onchange={event=>{void importFiles([...event.currentTarget.files]);event.currentTarget.value='';}}/>
 <footer><span>已选 {selection.selectedIds.length} / 共 {ids.length}</span><Button variant="subtle" onclick={()=>picker.click()}>添加图片</Button><Button variant="subtle" disabled={importing} onclick={folder}>文件夹</Button><Button disabled={!selection.selectedIds.length} aria-expanded={batch} onclick={()=>{batch=!batch;menu=null;}}>批量操作<ChevronDown size={13}/></Button></footer>
 {#if batch}<div class="asset-batch" role="group" aria-label="批量操作">{#each [['cutout','抠图'],['white','白底'],['center','居中'],['export','导出'],['trash','删除']] as [kind,label]}<Button onclick={()=>action(kind)}>{label}</Button>{/each}<RatioBar onerror={e=>error=e.message}/></div>{/if}
 </div>
 {#if menu}<div class="asset-context" role="menu" aria-label="素材操作" style:left={`${menu.x}px`} style:top={`${menu.y}px`}><button role="menuitem" onclick={open}>打开</button><button role="menuitem" onclick={mention}>@ 到对话</button><span>比例</span><RatioBar onerror={e=>error=e.message}/>{#each [['cutout','抠图'],['white','白底'],['export','导出'],['trash','删除']] as [kind,label]}<button role="menuitem" onclick={()=>action(kind)}>{label}</button>{/each}<button role="menuitem" onclick={()=>menu=null}>关闭菜单</button></div>{/if}
</section>
<style>.asset-library{--tree-w:220px;display:grid;grid-template-columns:var(--tree-w) 8px minmax(0,1fr);height:100%;min-height:0;font:13px system-ui,sans-serif;color:var(--text);background:var(--bg);position:relative}.asset-tree{min-height:0;overflow:auto;padding:16px 8px;background:var(--bg-elev);border-right:1px solid var(--border)}.asset-tree h2{font-size:12px;color:var(--text-dim);font-weight:500;margin:20px 12px 8px}.asset-tree h2:first-child{margin-top:0}.asset-tree p{font-size:12px;color:var(--text-dim);padding:0 12px}.asset-tree button{display:flex;align-items:center;gap:8px;width:100%;text-align:left;padding:8px 12px;border:0;border-radius:6px;background:transparent;color:var(--text);font:12px system-ui,sans-serif;cursor:pointer}.asset-tree button span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.asset-tree button small{margin-left:auto}.asset-tree button.chosen,.asset-filters button.chosen{background:var(--accent-soft);color:var(--accent)}.asset-library-main{display:grid;grid-template-rows:40px minmax(0,1fr) 36px;min-width:0;min-height:0;position:relative}.asset-filters{display:flex;align-items:center;gap:8px;padding:4px 12px;border-bottom:1px solid var(--border);min-width:0}.asset-filters input,.asset-filters select{background:var(--bg-elev);color:var(--text);border:1px solid var(--border);border-radius:6px;font:12px system-ui,sans-serif;min-height:28px;min-width:0;padding:4px 8px}.asset-search{display:flex;align-items:center;gap:6px;flex:1;min-width:80px}.asset-search input{width:100%}.asset-filters select{max-width:120px}.asset-filters button{display:flex;align-items:center;justify-content:center;flex:none;width:28px;height:28px;border:0;border-radius:6px;background:transparent;color:var(--text-dim);cursor:pointer}.asset-library footer{display:flex;align-items:center;gap:8px;padding:0 12px;border-top:1px solid var(--border);background:var(--bg-elev);font-size:12px}.asset-library footer>span{flex:1}.asset-library footer :global(button){min-height:28px;padding:2px 8px;font-size:12px}.asset-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;min-height:0}.asset-empty h2{font-size:14px;font-weight:500;margin:0}.asset-empty p{font-size:12px;color:var(--text-dim);margin:0}.asset-batch{position:absolute;right:12px;bottom:40px;display:flex;flex-wrap:wrap;align-items:center;gap:8px;max-width:calc(100% - 24px);padding:12px;border:1px solid var(--border);border-radius:8px;background:var(--bg-elev);z-index:10}.asset-context{position:fixed;z-index:50;display:flex;flex-direction:column;align-items:stretch;gap:4px;padding:8px;min-width:248px;background:var(--bg-elev);color:var(--text);border:1px solid var(--border);border-radius:8px;box-shadow:0 8px 20px #0002}.asset-context>button{padding:6px 8px;text-align:left;background:transparent;border:0;border-radius:4px;color:var(--text);font:12px system-ui,sans-serif;cursor:pointer}.asset-context>span{padding:4px 8px;font-size:11px;color:var(--text-dim)}.asset-tree button:hover,.asset-filters button:hover,.asset-context>button:hover{background:var(--bg-sunken)}.asset-tree button:active,.asset-filters button:active,.asset-context>button:active{background:var(--accent-soft)}.asset-library :where(button,input,select):focus-visible{outline:2px solid var(--focus);outline-offset:1px}.asset-error{position:absolute;z-index:12;top:40px;left:12px;right:12px;padding:12px;background:var(--bg-elev);color:var(--danger);font-size:12px;border:1px solid var(--border);border-radius:6px}</style>
